// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.accessibilityimport timber.log.Timberimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Accessibility Service Registry (Module 9 v1 — Step 9.1). * * Static holder for the active [NousAccessibilityService] instance. * * ## Why a static registry? * * Android's framework instantiates [AccessibilityService] — NOT Hilt. The * service is created when the user enables it in Settings → Accessibility, * and destroyed when they disable it. Other components (AutomationEngine, * ScreenUnderstandingEngine, etc.) need to access the active service instance, * but Hilt can't inject it (Hilt doesn't manage the lifecycle). * * This registry uses an [AtomicReference] to safely hold the active instance: *  - `onServiceConnected()` → [register] *  - `onUnbind()` → [unregister] *  - Other components → [getInstance] (returns null if service not active) * * This is the standard pattern used by all accessibility automation apps * (Tasker, Macrodroid, Greenify, etc.). * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Architecture → Pillar 3</a> */object AccessibilityServiceRegistry {    private const val TAG = "AccessibilityRegistry"    /** The active service instance (null when service is not connected). */    private val activeService = AtomicReference<NousAccessibilityService?>(null)    /**     * Register the active service instance.     *     * Called by [NousAccessibilityService.onServiceConnected].     */    fun register(service: NousAccessibilityService) {        val previous = activeService.getAndSet(service)        if (previous != null) {            Timber.tag(TAG).w("Previous service instance was still registered — replacing.")        }        Timber.tag(TAG).i("NousAccessibilityService registered.")    }    /**     * Unregister the active service instance.     *     * Called by [NousAccessibilityService.onUnbind].     */    fun unregister() {        activeService.set(null)        Timber.tag(TAG).i("NousAccessibilityService unregistered.")    }    /**     * Get the active service instance.     *     * @return the active [NousAccessibilityService], or null if the service     *         is not connected (user hasn't enabled it in Settings).     */    fun getInstance(): NousAccessibilityService? = activeService.get()    /**     * True if the service is currently active (connected + not unbound).     */    fun isActive(): Boolean = activeService.get() != null}